from pathlib import Path
import json,html
P=Path(__file__).parent
d=json.loads((P/'prd.json').read_text())
E=html.escape
pages=[]
def page(body,kind='chapter'):
 pages.append('<article class="page '+kind+'"><header><b>AgentCV</b><span>產品概念 PRD / v0.1 / 待審核</span></header>'+body+'<footer><span>2026-10-26 · 概念審核文件 · 圖中標記為示意，非檢測結果</span><b>'+str(len(pages)+1).zfill(2)+'</b></footer></article>')
page('''<div class="eyebrow">PRODUCT REQUIREMENTS DOCUMENT</div><h1 class="cover-title">以畫板表達意圖<br>以證據建立流程</h1><p class="subtitle">AgentCV · Agent 驅動的視覺檢測協作平台</p><div class="cover-image"><img src="assets/crystal-camera.png"><div>圖像 ＋ 標記 ＋ 關係<br><strong>→ 可解釋、可驗證的檢測方案</strong></div></div><div class="cover-notes"><p><b>本版目的</b>　對齊產品核心、操作邏輯與驗收方向，避免先改軟體再發現概念錯誤。</p><p><b>審核狀態</b>　v0.1 草案。會話方向共識與具體設計提案分開；尚未獲用戶批准。</p><p><b>文件邊界</b>　本輪只製作 PRD，沒有修改產品或執行檢測。素材與示意不構成算法效果證明。</p></div><div class="toc"><b>閱讀路線</b><p>核心與資料 → 依賴流程 → 畫板交互 → 解釋契約 → 晶振故事 → 通用案例 → 驗收與待定事項</p></div>''','cover')
for c in d['chapters']:
 body='<div class="eyebrow">'+E(c['kicker'])+'</div><h1>'+E(c['title'])+'</h1><p class="lead">'+E(c['lead'])+'</p><figure>'+c['diagram']+'</figure><div class="principles">'+''.join('<div><h2>'+E(a)+'</h2><p>'+E(b)+'</p></div>' for a,b in c['items'])+'</div><div class="criteria"><h3>本章審核點</h3><ul>'+''.join('<li>'+E(t)+'</li>' for t in c['criteria'])+'</ul></div>'
 if c['id']=='evidence':body+='<p class="source">依據：Pi 日誌的三份唯讀審查。主要缺口包括用途解釋代替選值依據、第一組固定輸出、局部失效被總體 PASS 掩蓋，以及歷史失敗未延續。</p>'
 page(body)
 if c['extra']:
  titles={'crystal':('用戶故事 / 逐幕審核','晶振：工程師與 Agent 如何走完整個任務'),'coverage':('跨案例 / 通用性審核','十種需求，同一套表達與核對方式'),'delivery':('待決事項 / 審核紀錄','這些細節還沒有定案')}
  k,t=titles[c['id']]
  extra=c['extra']
  if c['id']=='delivery':extra+='''<div class="review-box"><h2>本輪建議審核順序</h2><ol><li>先確認節點、步驟、試驗及依賴的概念。</li><li>再確認就地詢問、距離控件、跨節點切換的故事。</li><li>最後討論證據門檻、試驗預算與正式採用方式。</li></ol><p>確認後再形成具體交互稿與實作拆分。本文件不是軟體已完成的聲明。</p></div><div class="sources"><h2>來源與延伸審核資料</h2><p>① 本會話：產品核心、目標反推依賴、畫板原位詢問、距離控件及優化共識。</p><p>② 既有晶振原圖及 OpenCV 用例收集：原始用例與來源保留於同項目 prd 目錄。</p><p>③ 2026-10-26 Pi 審查：content-audit.json、execution-audit.json、host-audit.json。</p><p>④ 工程本體 skill：OntologyEngineering v2.0.0-rc.7。只參照目標、來源、前提、證據與版本方法；本項目沒有因此聲稱已安裝其工程執行系統。</p></div>'''
  page('<div class="eyebrow">'+k+'</div><h1>'+t+'</h1><p class="lead">用來審核交互與概念，不預定算法，也不冒充實際測試結果。</p>'+extra,'appendix')
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Noto Sans TC",sans-serif;color:#244036;background:#e9ede5;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{width:210mm;height:297mm;padding:15mm 15mm 18mm;background:#faf9f4;position:relative;break-after:page;overflow:visible}.page:last-child{break-after:auto}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #b8cbbd;padding-bottom:11px;margin-bottom:25px;font-size:11px;color:#67806b}header b{font-size:18px;color:#234d39}.eyebrow{font-size:11px;letter-spacing:1.5px;color:#5d886e;font-weight:700}h1{font-size:27px;line-height:1.35;margin:12px 0 10px;letter-spacing:-.6px}.lead{font-size:14px;line-height:1.8;color:#617264;margin:0 0 20px}figure{margin:0 0 24px}svg{width:100%;display:block;height:auto}svg text{font-family:-apple-system,BlinkMacSystemFont,"Noto Sans TC",sans-serif}.principles{display:grid;grid-template-columns:1fr;gap:16px}.principles>div{display:grid;grid-template-columns:95px minmax(0,1fr);gap:15px;border-top:1px solid #dbe3d5;padding-top:13px}h2{font-size:14px;line-height:1.6;margin:0;color:#315b40}p{font-size:13px;line-height:1.85;margin:0}.principles p{color:#5a6b5e}.criteria{margin-top:22px;background:#eaf0e5;padding:15px 18px;border-radius:7px}h3{font-size:12px;margin:0 0 6px}ul,ol{margin:0;padding-left:19px;font-size:12px;line-height:1.85}li{margin:5px 0}footer{position:absolute;bottom:10mm;left:15mm;right:15mm;display:flex;justify-content:space-between;border-top:1px solid #d4dfd0;padding-top:9px;font-size:10px;color:#7a8c7c}.source{margin-top:12px;color:#7b897d;font-size:11px}.cover-title{font-size:42px;line-height:1.4;margin-top:20px}.subtitle{font-size:17px;color:#5b7763;margin:15px 0 25px}.cover-image{position:relative;height:300px;overflow:hidden;border-radius:10px;background:#19231c}.cover-image img{width:100%;height:100%;object-fit:contain;opacity:.8}.cover-image div{position:absolute;bottom:0;left:0;width:100%;background:linear-gradient(transparent,#172b20);padding:40px 22px 20px;color:#fff;font-size:17px;line-height:1.9}.cover-notes{margin-top:27px}.cover-notes p{margin-top:13px;font-size:13px}.toc{border-top:1px solid #bdcebe;margin-top:26px;padding-top:17px;font-size:13px}.toc p{margin-top:8px;color:#6d7f70}.story{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:35px}.story div{background:#edf2e8;border-radius:8px;padding:22px;min-height:190px}.story b{font-size:17px;color:#315b40}.story p{margin-top:14px;font-size:14px}.tablewrap{margin-top:25px}table{border-collapse:collapse;width:100%;font-size:12px;line-height:1.7}th,td{border-bottom:1px solid #d9e2d2;padding:12px 10px;text-align:left;vertical-align:top}th{background:#e8efdf}td:first-child{width:25%;font-weight:600}td:nth-child(2){width:30%}.small{font-size:11px;color:#7a897c;margin-top:15px}a{color:#377452;text-decoration:none}.review-box{padding:20px;background:#edf2e7;margin-top:28px;border-radius:9px}.review-box ol{margin:12px 0}.sources{margin-top:26px}.sources p{font-size:11px;color:#768577;margin-top:8px}@media screen{.page{margin:20px auto;box-shadow:0 5px 25px #0001}}'''
(P/'print.html').write_text('<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><title>AgentCV 產品概念 PRD v0.1</title><style>'+css+'</style></head><body>'+''.join(pages)+'</body></html>')
print(json.dumps({'pages':len(pages),'layout':'A4 portrait','scope':'PRD only'}))
